"""Small pure-function toolkit for invoice validation, event sorting, and amount summaries."""

from __future__ import annotations

from typing import Any, Iterable, Mapping, Sequence


def is_mapping(value: Any) -> bool:
    """Return True if value is a mapping-like object."""
    return isinstance(value, Mapping)


def is_invoice(value: Any) -> bool:
    """Return True if value is a mapping suitable for invoice processing."""
    return is_mapping(value)


def has_key(invoice: Mapping[str, Any], key: str) -> bool:
    """Return True if invoice contains key."""
    return key in invoice


def get_field(invoice: Mapping[str, Any], key: str, default: Any = None) -> Any:
    """Return invoice field value or default."""
    return invoice.get(key, default)


def is_nonempty_string(value: Any) -> bool:
    """Return True if value is a nonempty string."""
    return isinstance(value, str) and value.strip() != ""


def is_number(value: Any) -> bool:
    """Return True if value is an int or float but not bool."""
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def is_positive_number(value: Any) -> bool:
    """Return True if value is a positive number."""
    return is_number(value) and value > 0


def is_nonnegative_number(value: Any) -> bool:
    """Return True if value is a nonnegative number."""
    return is_number(value) and value >= 0


def is_integer(value: Any) -> bool:
    """Return True if value is an integer but not bool."""
    return isinstance(value, int) and not isinstance(value, bool)


def is_positive_integer(value: Any) -> bool:
    """Return True if value is a positive integer."""
    return is_integer(value) and value > 0


def is_sequence(value: Any) -> bool:
    """Return True if value is a sequence but not a string."""
    return isinstance(value, Sequence) and not isinstance(value, str)


